public int secondLargest(int[] arr) {
    int largest = Math.max(arr[0], arr[1]);
    int second = Math.min(arr[0], arr[1]);
    for (int i = 2; i < arr.length; i++) {
        if (arr[i] > largest) {
            second = largest;
            largest = arr[i];
        } else if (arr[i] > second) {
            second = arr[i];
        }
    }
    return second;
}
```
